import{_ as e,c as r,a2 as a,o as s}from"./chunks/framework.CoXjB5sU.js";const u=JSON.parse('{"title":"Steps prior installation","description":"","frontmatter":{},"headers":[],"relativePath":"doc/guides/installation/required-steps.md","filePath":"doc/guides/installation/required-steps.md"}'),i={name:"doc/guides/installation/required-steps.md"};function o(d,t,n,l,h,c){return s(),r("div",null,t[0]||(t[0]=[a('<h1 id="steps-prior-installation" tabindex="-1">Steps prior installation <a class="header-anchor" href="#steps-prior-installation" aria-label="Permalink to &quot;Steps prior installation&quot;">​</a></h1><p>The installer asks for the parameters listed on this page. Gather them before you start. The <em>Parameter</em> column is the key name in the installation parameters file used by <a href="./installation.html#unattended-installation">unattended installations</a>.</p><h2 id="web-service-and-https-certificate" tabindex="-1">Web service and HTTPS certificate <a class="header-anchor" href="#web-service-and-https-certificate" aria-label="Permalink to &quot;Web service and HTTPS certificate&quot;">​</a></h2><p>ioChem-BD should run on a machine that is publicly reachable:</p><ul><li>Users can access it from anywhere.</li><li>Your published datasets become Open Data and Open Science.</li><li>Your instance can synchronise its public data with the <a href="https://www.iochem-bd.org" target="_blank" rel="noreferrer">central ioChem-BD repository</a>.</li></ul><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>You can ask for your ioChem-BD instance to be synchronised with the central service by <a href="https://www.iochem-bd.org/home.jsp?action=requestAccount" target="_blank" rel="noreferrer">filling in this form</a>.</p></div><table tabindex="0"><thead><tr><th>Parameter</th><th>Description</th><th>Sample values</th></tr></thead><tbody><tr><td><strong>hostName</strong></td><td>Fully qualified hostname of the server. All modules are served under <code>https://&lt;hostName&gt;/</code>.</td><td>iochem-bd.iciq.es / iochembd.university.edu</td></tr><tr><td><strong>institutionName</strong></td><td>Name of your institution, shown in Browse and in exported content. Avoid acronyms; no <code>\\</code> or <code>$</code> characters.</td><td>Institute of Chemical Research of Catalonia</td></tr><tr><td><strong>isPublicServer</strong></td><td>Set it to true for a public server open to the whole community. It turns off the Create features that let users find each other&#39;s data (sharing and searching other users&#39; projects).</td><td>false</td></tr><tr><td><strong>tlsMode</strong></td><td>How the HTTPS certificate is obtained, see below.</td><td>selfsigned / provided / acme</td></tr></tbody></table><p>Every communication (user browser, shell client and module to module) runs over HTTPS. The installer offers three ways to get the certificate:</p><table tabindex="0"><thead><tr><th>Mode (<code>tlsMode</code>)</th><th>When to use it</th><th>Extra parameters</th></tr></thead><tbody><tr><td>Self-signed certificate (<code>selfsigned</code>)</td><td>Tests and internal servers. Browsers will show a security warning.</td><td>none</td></tr><tr><td>Certificate files provided (<code>provided</code>)</td><td>Your institution issues the certificate. Use PEM files readable by the installation user.</td><td><strong>certificateFile</strong>, <strong>certificateKeyFile</strong>, <strong>certificateChainFile</strong> (optional)</td></tr><tr><td>Let&#39;s Encrypt (<code>acme</code>)</td><td>The hostname is a public DNS name and ports 80/443 are reachable from the Internet. The proxy obtains and renews the certificate automatically.</td><td><strong>acmeEmail</strong> (optional contact address)</td></tr></tbody></table><p>You can change the certificate later, see <a href="./../other-operations/replace-https-certificate.html">Replace HTTPS certificate</a>.</p><h2 id="mail-settings" tabindex="-1">Mail settings <a class="header-anchor" href="#mail-settings" aria-label="Permalink to &quot;Mail settings&quot;">​</a></h2><p>ioChem-BD sends notifications by email: account registration, password reset, publication and review messages. Create an email account for ioChem-BD at your institution, or use an existing address as the sender.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Description</th><th>Sample values</th></tr></thead><tbody><tr><td><strong>mailServer</strong></td><td>SMTP server hostname</td><td>smtp.university.edu</td></tr><tr><td><strong>mailServerPort</strong></td><td>SMTP server port</td><td>25 / 465 (SSL) / 587 (STARTTLS)</td></tr><tr><td><strong>mailIsSSL</strong></td><td>The server uses SSL from the start (usually port 465)</td><td>false</td></tr><tr><td><strong>mailIsSTARTTLS</strong></td><td>The server upgrades the connection with STARTTLS (usually port 587)</td><td>true</td></tr><tr><td><strong>mailFromAddress</strong></td><td>Sender address of every notification (required)</td><td><a href="mailto:iochembd@university.edu" target="_blank" rel="noreferrer">iochembd@university.edu</a></td></tr><tr><td><strong>mailServerUsername</strong></td><td>(Optional) Account username, if the server requires authentication</td><td><a href="mailto:iochembd@university.edu" target="_blank" rel="noreferrer">iochembd@university.edu</a></td></tr><tr><td><strong>mailServerPassword</strong></td><td>(Optional) Account password, if the server requires authentication</td><td></td></tr></tbody></table><h2 id="database-settings" tabindex="-1">Database settings <a class="header-anchor" href="#database-settings" aria-label="Permalink to &quot;Database settings&quot;">​</a></h2><p>ioChem-BD stores its data in two PostgreSQL databases, <em>iochemCreate</em> and <em>iochemBrowse</em>. Both must exist, be empty and be owned by the same user. They are created during the <a href="./installation.html#prepare-the-databases">installation procedure</a>.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Description</th><th>Sample values</th></tr></thead><tbody><tr><td><strong>databaseHost</strong></td><td>PostgreSQL server hostname</td><td>localhost</td></tr><tr><td><strong>databasePort</strong></td><td>PostgreSQL server port</td><td>5432</td></tr><tr><td><strong>databaseUser</strong></td><td>Owner of both databases</td><td>iochembd</td></tr><tr><td><strong>databasePwd</strong></td><td>Password of the database user</td><td></td></tr><tr><td><strong>databaseIsSSL</strong></td><td>Connect to the database over SSL</td><td>false</td></tr></tbody></table><h2 id="administrator-account-settings" tabindex="-1">Administrator account settings <a class="header-anchor" href="#administrator-account-settings" aria-label="Permalink to &quot;Administrator account settings&quot;">​</a></h2><p>The installer creates the first user of the platform, the administrator. This account manages users, groups, communities and the platform configuration. It logs in through the same login page as every other user.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>For security reasons, the administrator should create a separate <strong>non-admin</strong> account to work in the <em>Create</em> module as a regular user.</p></div><table tabindex="0"><thead><tr><th>Parameter</th><th>Description</th><th>Sample values</th></tr></thead><tbody><tr><td><strong>adminEmail</strong></td><td>Administrator email, also used as the login username</td><td><a href="mailto:iochembd-admin@university.edu" target="_blank" rel="noreferrer">iochembd-admin@university.edu</a></td></tr><tr><td><strong>adminFirstName</strong>, <strong>adminLastName</strong></td><td>Display name of the administrator</td><td>Admin / ioChem-BD</td></tr><tr><td><strong>adminPassword</strong></td><td>Administrator password (at least 8 characters)</td><td></td></tr></tbody></table>',20)]))}const p=e(i,[["render",o]]);export{u as __pageData,p as default};
